type TranslationParts={natural:string;literal:string;pronunciation:string;note:string;example:string};
function parseTranslation(text:string):TranslationParts{
  const out:TranslationParts={natural:'',literal:'',pronunciation:'',note:'',example:''};
  const labels:[keyof TranslationParts,string[]][]=[['natural',['ترجمه طبیعی','natural']],['literal',['ترجمه تحت‌اللفظی','ترجمه تحت اللفظی','literal']],['pronunciation',['تلفظ','pronunciation']],['note',['نکته','note']],['example',['مثال','example']]];
  for(const [key,names] of labels){const re=new RegExp(`(?:^|\\n)\\s*(?:${names.map(x=>x.replace(/[.*+?^${}()|[\\]\\]/g,'\\$&')).join('|')})\\s*[:：-]\\s*([^\\n]*)`,'i');const m=text.match(re);if(m)out[key]=(m[1]||'').trim();}
  if(!out.natural) out.natural=text.trim();
  return out;
}

async function speak(text:string,lang='ar-IQ'){
  if(Capacitor.isNativePlatform()){
    const sherpa=listSherpaTtsModels().find(x=>lang.toLowerCase().startsWith(x.language.toLowerCase())||x.dialect.toLowerCase()===lang.toLowerCase());
    if(sherpa){
      try{await speakOffline(text,{model:sherpa.model,tokens:sherpa.tokens,dataDir:sherpa.dataDir,lexicon:sherpa.lexicon,speed:getSpeechSpeed()});return;}
      catch(e:any){await addLog('warn',`Sherpa TTS failed; Android TTS fallback: ${e?.message||e}`)}
    }
    try{await NativeTTS.speak({text,lang,rate:getSpeechSpeed(),pitch:1});}
    catch(e:any){await addLog('warn',`TTS failed: ${e?.message||e}`)}
    return;
  }
  try{const u=new SpeechSynthesisUtterance(text);u.lang=lang;u.rate=getSpeechSpeed();speechSynthesis.cancel();speechSynthesis.speak(u)}catch{}
}
async function copyText(text:string){
  try{await navigator.clipboard.writeText(text);return true}catch{}
  try{const ta=document.createElement('textarea');ta.value=text;ta.style.position='fixed';ta.style.opacity='0';document.body.appendChild(ta);ta.focus();ta.select();const ok=document.execCommand('copy');ta.remove();return ok}catch{return false}
}
function localAnswer(text:string){const exact=searchBank(text.trim(),3)[0];if(exact)return `پاسخ از بانک محلی:\n${exact.translation||exact.definition||exact.text}\n\nعبارت مرتبط: ${exact.text}`;return /[\u0600-\u06FF]/.test(text)?'مدل محلی یا سرویس آنلاین در دسترس نبود. بانک زبان محلی همچنان فعال است.':'The local language bank is available, but no AI model is currently ready.'}

function similarityScore(a:string,b:string){if(!a||!b)return 0;const dp=Array.from({length:a.length+1},()=>Array<number>(b.length+1).fill(0));for(let i=0;i<=a.length;i++)dp[i]![0]=i;for(let j=0;j<=b.length;j++)dp[0]![j]=j;for(let i=1;i<=a.length;i++)for(let j=1;j<=b.length;j++)dp[i]![j]=a.charAt(i-1)===b.charAt(j-1)?dp[i-1]![j-1]! :1+Math.min(dp[i-1]![j]!,dp[i]![j-1]!,dp[i-1]![j-1]!);return Math.max(0,Math.round((1-dp[a.length]![b.length]!/Math.max(a.length,b.length))*100));}

