  const due=useMemo(()=>getDueItems(supportedBank),[supportedBank]);
  const learningPlan=useMemo(()=>buildLearningPlan(supportedBank,12),[supportedBank]);
  const dialectPlan=useMemo(()=>buildDialectLearningPlan(supportedBank,learnDialect,24),[supportedBank,learnDialect]);
  const dialectState=getDialectLearningState(learnDialect); const dialectInsights=getDialectLearningInsights(learnDialect);
